<section class="auth-page"><div class="container auth-single"><div class="auth-card surface"><header><span class="eyebrow">Reset Password</span><h1>تنظیم رمز عبور جدید</h1></header><?php if ($success): ?><div class="alert alert--success" role="status"><strong>رمز عبور شما با موفقیت تغییر کرد.</strong><p>اکنون می‌توانید با رمز جدید وارد شوید.</p></div><a class="btn btn--primary btn--lg w-full" href="/login">ورود به حساب</a><?php elseif (!$valid): ?><div class="alert alert--danger" role="alert"><strong>این لینک نامعتبر یا منقضی شده است.</strong><p>لینک بازیابی فقط یک‌بار و تا یک ساعت قابل استفاده است.</p></div><a class="btn btn--secondary w-full" href="/forgot-password">درخواست لینک جدید</a><?php else: ?><?php if ($errors): ?><div class="alert alert--danger" role="alert"><strong>لطفاً رمز عبور را بررسی کنید.</strong></div><?php endif; ?><form class="stack" method="post" action="/reset-password/<?= e($token) ?>"><?= csrf_field() ?><label class="form-group"><span class="form-label">رمز عبور جدید</span><input class="form-control ltr" type="password" name="password" autocomplete="new-password" minlength="8" maxlength="72" required><?php if (isset($errors['password'])): ?><span class="form-error"><?= e($errors['password'][0]) ?></span><?php endif; ?></label><label class="form-group"><span class="form-label">تکرار رمز جدید</span><input class="form-control ltr" type="password" name="password_confirmation" autocomplete="new-password" required><?php if (isset($errors['password_confirmation'])): ?><span class="form-error"><?= e($errors['password_confirmation'][0]) ?></span><?php endif; ?></label><button class="btn btn--primary btn--lg w-full" type="submit">ذخیره رمز جدید</button></form><?php endif; ?></div></div></section>
